/* the letterhead image, once; the logo images below are filled from it */
(function(){var L="data:image/png;base64,";window.NBH_LOGO=L;function fill(){var a=document.querySelectorAll('img[data-nbh-logo]');for(var i=0;i<a.length;i++)if(!a[i].getAttribute("src"))a[i].setAttribute("src",L);}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",fill);else fill();window.addEventListener("beforeprint",fill);})();